\documentclass[11pt]{article}
\usepackage{amsmath,amssymb}

\title{Convergence of a Godunov-Type Scheme for Sediment Transport in Alluvial Channels}
\author{H.~Okafor and S.~Lindqvist}
\date{June 2026}

\begin{document}
\maketitle

\begin{abstract}
We analyse a finite volume discretisation of the coupled shallow
water--Exner system with a regularised friction closure. The scheme
remains well balanced at dry fronts, and numerical tests on dune
migration show mesh-independent bed profiles.
\end{abstract}

